css:
.ataa-print { direction: rtl; text-align: right; font-family: "IBM Plex Sans Arabic", "Tajawal", sans-serif; color: #1f1d1a; }
.ataa-print .head { border-bottom: 3px solid #AD8F52; padding-bottom: 8px; margin-bottom: 14px; }
.ataa-print h1 { font-size: 22px; margin: 0; color: #7a6233; }
.ataa-print h2 { font-size: 16px; margin: 18px 0 8px; color: #7a6233; }
.ataa-print .ref { font-weight: bold; }
.ataa-print table { width: 100%; border-collapse: collapse; }
.ataa-print .facts th { width: 16%; color: #6b6458; font-weight: normal; padding: 4px; }
.ataa-print .facts td { padding: 4px; }
.print-hide, .action-banner { display: none !important; }
.ataa-print .totals { margin: 14px 0; border-collapse: separate; border-spacing: 8px 0; }
.ataa-print .totals td { width: 33%; border: 1px solid #e6dcc6; border-radius: 8px; padding: 8px; background: #faf6ee; }
.ataa-print .totals span { display: block; color: #6b6458; font-size: 12px; }
.ataa-print .totals b { font-size: 16px; }
.ataa-print .lines th, .ataa-print .lines td { border: 1px solid #e6dcc6; padding: 5px 6px; }
.ataa-print .lines thead th { background: #f3ecdd; }
.ataa-print .lines tfoot td { font-weight: bold; background: #faf6ee; }
.ataa-print .je { color: #6b6458; font-size: 11px; }
.ataa-print .invoice { page-break-inside: avoid; border: 1px solid #e6dcc6; border-radius: 8px; padding: 8px; margin-bottom: 10px; }
.ataa-print .invoice .cap { font-weight: bold; margin-bottom: 6px; }
.ataa-print .invoice img { max-width: 100%; max-height: 520px; display: block; margin: 0 auto; }
.ataa-print .invoice .file { color: #6b6458; }
